import{c as s,Q as a,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const p="/assets/batchmode%E8%B5%84%E6%96%99.pqruDBnu.png",d=JSON.parse('{"title":"SIMD BuiltIn关键字","description":"","frontmatter":{},"headers":[{"level":1,"title":"SIMD BuiltIn关键字","slug":"simd-builtin关键字"},{"level":2,"title":"预定义宏","slug":"预定义宏"},{"level":2,"title":"函数执行空间限定符","slug":"函数执行空间限定符"},{"level":2,"title":"函数标记宏","slug":"函数标记宏"},{"level":2,"title":"地址空间限定符","slug":"地址空间限定符"},{"level":2,"title":"内置常量","slug":"内置常量"},{"level":2,"title":"内置变量","slug":"内置变量"},{"level":2,"title":"SIMD与SIMT混合编程场景","slug":"simd与simt混合编程场景"}],"relativePath":"guide/编程指南/语言扩展层/SIMD-BuiltIn关键字.md","filePath":"guide/编程指南/语言扩展层/SIMD-BuiltIn关键字.md"}'),e={name:"guide/编程指南/语言扩展层/SIMD-BuiltIn关键字.md"};function o(i,t,_,c,u,g){return a(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="simd-builtin关键字" tabindex="-1">SIMD BuiltIn关键字 <a class="header-anchor" href="#simd-builtin关键字" aria-label="Permalink to &quot;SIMD BuiltIn关键字&quot;">​</a></h1><h2 id="预定义宏" tabindex="-1">预定义宏 <a class="header-anchor" href="#预定义宏" aria-label="Permalink to &quot;预定义宏&quot;">​</a></h2><p>如其他语言一样，会提供一些内置的宏方便用户编写程序。预定义宏一节着重介绍一些用户在做异构编程时会经常用到的宏，以及宏的解释。</p><ul><li><p><strong>__NPU_ARCH__</strong></p><p>__NPU_ARCH__是Device侧AI Core代码中的预处理宏，用于标识AI处理器的架构版本。该宏由四位数字组成，其中前三位数字用于标识AI Core的IP核(Intellectual Property Core)类型，第四位数字标识该AI Core同一个IP核的配置版本。通过该宏，开发者可以针对不同AI处理器，差异化进行代码适配和优化。AI处理器型号和__NPU_ARCH__对应关系如下表所示：</p><p><strong>表 1</strong> AI处理器型号和__NPU_ARCH__的对应关系</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;AI处理器&lt;/span&gt;型号&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;<strong>NPU_ARCH</strong>&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;3510&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas A3 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A3 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;2201&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas A2 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A2 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;2201&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 200I/500 A2 推理产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;3002&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;2002&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.59%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 训练系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.41%&quot;&gt;&lt;p&gt;1001&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>以下为通过__NPU_ARCH__控制在不同AI处理器上算子输出值舍入模式的示例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ static inline void CopyOut(uint64_t mulLen)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>#if __NPU_ARCH__ == 2002</span></span>
<span class="line"><span>    Cast(dstLocal, srcLocal, RoundMode::CAST_NONE, mulLen); // CAST_NONE表示舍入模式在转换有精度损失时使用CAST_RINT模式，在不涉及精度损失时不进行舍入</span></span>
<span class="line"><span>#elif __NPU_ARCH__ == 2201</span></span>
<span class="line"><span>    Cast(dstLocal, srcLocal, RoundMode::CAST_RINT, mulLen); // CAST_RINT表示舍入模式为四舍六入五成双舍入</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>    event_t eventVToMTE3 = static_cast&lt;event_t&gt;(GetTPipePtr()-&gt;FetchEventID(HardEvent::V_MTE3));</span></span>
<span class="line"><span>    SetFlag&lt;HardEvent::V_MTE3&gt;(eventVToMTE3);</span></span>
<span class="line"><span>    WaitFlag&lt;HardEvent::V_MTE3&gt;(eventVToMTE3);</span></span>
<span class="line"><span>    CommonCopyOut&lt;float&gt;(dstLocal, mulLen);  // 拷贝LocalTensor至GlobalTensor</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>ASCEND_IS_AIV、ASCEND_IS_AIC</strong></p><p>ASCEND_IS_AIV和ASCEND_IS_AIC是通过C++宏实现的条件判断语句，用于在__aicore__修饰的函数中实现代码的条件编译。基于分离模式（AIC核和AIV核分离）开发融合算子时，算子逻辑中同时涉及AIV核和AIC核的处理逻辑，并需要进行核间同步，此时需要通过ASCEND_IS_AIV/ ASCEND_IS_AIC进行AIV和AIC核代码的隔离。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>当使用高阶API Matmul时，其内部已通过REGIST_MATMUL_OBJ宏方式实现了AIV与AIC核代码的隔离，用户无需再使用该宏进行处理。</p></div><p>以MatmulNzCustom算子为例，该算子在分离模式下需要分别在AIV核和AIC核上实现不同的逻辑。具体而言，AIV核负责将矩阵数据搬入Unified Buffer，完成数据的重排（将矩阵数据转换为NZ格式），并将其写入Global Memory。而AIC核则直接从Global Memory读取已经重排好的NZ格式数据，并执行矩阵乘法（Matmul）计算。由于AIV核和AIC核的代码逻辑不同，需要通过ASCEND_IS_AIV和ASCEND_IS_AIC宏进行代码隔离，确保在编译时分别生成适用于AIV核和AIC核的代码。</p><p>示例伪码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename AType, typename BType, typename CType, typename BiasType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulKernel&lt;AType, BType, CType, BiasType&gt;::Process(AscendC::TPipe *pipe)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // 利用AIV核的Vector计算单元实现ND2NZ格式转换。如下代码中MatrixBtoNZ为将B矩阵进行ND2NZ格式转换的函数。</span></span>
<span class="line"><span>    if ASCEND_IS_AIV {</span></span>
<span class="line"><span>        pipe-&gt;InitBuffer(ubBuf, TOTAL_UB_SIZE);</span></span>
<span class="line"><span>        MatrixBtoNZ&lt;typename B_TYPE::T&gt;(tempGM,</span></span>
<span class="line"><span>            bGMNZ,</span></span>
<span class="line"><span>            tiling,</span></span>
<span class="line"><span>            isTransB,</span></span>
<span class="line"><span>            ubBuf,</span></span>
<span class="line"><span>            tiling.baseK,</span></span>
<span class="line"><span>            tiling.baseN);  // Vector侧实现的ND2NZ函数</span></span>
<span class="line"><span>        SyncAll();</span></span>
<span class="line"><span>        // AIC核和AIV核同步</span></span>
<span class="line"><span>        AscendC::CrossCoreSetFlag&lt;0x2, PIPE_MTE3&gt;(0x4);</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if ASCEND_IS_AIC {</span></span>
<span class="line"><span>        AscendC::CrossCoreWaitFlag(0x4);   // 等待AIV核完成ND2NZ格式转换</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ... ...</span></span>
<span class="line"><span>    // 设置左矩阵A、右矩阵B、Bias。</span></span>
<span class="line"><span>    matmulObj.SetTail(tailM, tailN);</span></span>
<span class="line"><span>    matmulObj.SetTensorA(aGlobal, false);</span></span>
<span class="line"><span>    matmulObj.SetTensorB(bGlobal, false);</span></span>
<span class="line"><span>    if (tiling.isBias) {</span></span>
<span class="line"><span>        matmulObj.SetBias(biasGlobal);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // 完成矩阵乘操作</span></span>
<span class="line"><span>    matmulObj.IterateAll(cGlobal);</span></span>
<span class="line"><span>    // 结束矩阵乘操作</span></span>
<span class="line"><span>    matmulObj.End();</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>ASCENDC_CUBE_ONLY</strong></p><p>ASCENDC_CUBE_ONLY是通过C++宏实现的条件判断语句，用于在__aicore__修饰的函数中实现代码的条件编译。</p><p>基于分离模式开发非融合算子时，在只有矩阵计算的算子场景下，可以通过设置ASCENDC_CUBE_ONLY，使能纯Cube模式完成Matmul计算，减少消息通信的性能开销，提升算子性能。</p><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>ASCENDC_CUBE_ONLY宏必须在#include &quot;lib/matmul_intf.h&quot;之前设置。</p></div><p>以matmul_custom算子为例，高阶API Matmul默认使用MIX模式，即用户从AIV侧发起消息，通过消息通信框架中转消息后，在AIC侧执行Matmul计算。这套消息处理机制会带来额外的Scalar性能开销。相较于MIX模式，纯Cube模式可以直接跳过消息通信框架，完成Matmul计算，提升算子性能。</p><p>示例伪码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span></span>
<span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_NORM&gt; matmulObj;</span></span></code></pre></div></li></ul><h2 id="函数执行空间限定符" tabindex="-1">函数执行空间限定符 <a class="header-anchor" href="#函数执行空间限定符" aria-label="Permalink to &quot;函数执行空间限定符&quot;">​</a></h2><p>函数执行空间限定符（Function Execution Space Qualifier）指示函数是在Host侧执行还是在Device侧执行，以及它是否可从Host侧或Device侧调用。</p><ul><li><p><strong>__global__</strong></p><p>__global__执行空间限定符声明一个Kernel函数。Kernel函数有如下性质：在Device上执行；只能被Host侧函数调用；__global__只是表示这是Device侧函数的入口，并不表示具体的设备类型，具体的设备类型由__aicore__标记。具有如下使用约束：</p><ul><li>一个__global__函数必须返回void类型，并且不能是class的成员函数。</li><li>主机侧调用__global__函数必须使用&lt;&lt;&lt;&gt;&gt;&gt;异构调用语法。</li><li>__global__的调用是异步的，意味着函数返回，并不表示kernel函数在device侧已经执行完成，如果需要同步，需要使用Runtime同步接口显式同步，如<strong>aclrtSynchronizeStream</strong>接口。</li></ul></li><li><p><strong>__aicore__</strong></p><p>__aicore__执行空间限定符声明一个函数，它具有如下属性：</p><ul><li>在Device侧执行</li><li>只能被__global__函数，或者其他__aicore__函数调用</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Only callable from device functions with same kind</span></span>
<span class="line"><span>// of execution space</span></span>
<span class="line"><span>__aicore__ void bar() {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Define a kernel function execute on AI Core device</span></span>
<span class="line"><span>__global__ __aicore__ void foo() {</span></span>
<span class="line"><span>  bar(); // OK.</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>__host__</strong></p><p>__host__执行空间限定符声明一个函数，它具有如下属性：</p><ul><li>只能在Host侧执行</li><li>只能被Host侧函数调用</li><li>__global__ 和__host__不能一起使用</li></ul><p>__host__限定符是可选项，无函数执行空间限定符定义的函数，默认是host函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ int f() {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// defines a host side function</span></span>
<span class="line"><span>int foo() {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// defines a host side function</span></span>
<span class="line"><span>__host__ int bar() {</span></span>
<span class="line"><span>  f();     // Error.</span></span>
<span class="line"><span>  foo();   // OK.</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Error.</span></span>
<span class="line"><span>__global__ __host__ void kfunc() {}</span></span></code></pre></div></li><li><p><strong>__aicpu__</strong></p><p>AI CPU函数执行空间限定符__aicpu__用于指示函数是否为AI CPU Kernel函数，它具有如下属性：</p><ul><li>在Device侧执行且只能被Host侧函数调用，因此必须与__global__同时声明。</li><li>一个__global__ __aicpu__函数不能是void返回类型，并且入参只能是一个指针。</li><li>一个__global__ __aicpu__函数不能在.asc文件中进行定义，只能声明，且需要使用extern。</li><li>Host侧调用__global__ __aicpu__函数时必须使用&lt;&lt;&lt;&gt;&gt;&gt;异构调用语法，输入的函数入参在入参指针的基础上需要输入从指针中读取的数据大小。</li><li>__global__的调用是异步的，意味着函数返回，并不表示kernel函数在Device侧已经执行完成，如果需要同步，需要使用Runtime同步接口显式同步，如<strong>aclrtSynchronizeStream</strong>接口</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Define a AI CPU kernel function in AI CPU device file</span></span>
<span class="line"><span>__aicpu__ void foo() {} // Error, single __aicpu__ identifier without _global__</span></span>
<span class="line"><span>__global__ void foo() {} // Error, single __global__ identifier without __aicpu__ </span></span>
<span class="line"><span>__global__ __aicpu__  void foo() {} // Error, return type is void</span></span>
<span class="line"><span>__global__ __aicpu__  int foo(void *a) {} // OK </span></span>
<span class="line"><span>__global__ __aicpu__  int foo(int a) {} // Error, input param is not pointer</span></span>
<span class="line"><span>__global__ __aicpu__  int foo(void *a, void *b) {} // Error, input param num is not one</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Declare a AI CPU kernel function in .asc file</span></span>
<span class="line"><span>extern __global__ __aicpu__ uint32_t hello_world(void *args);// OK</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>__inline__</strong></p><p>__inline__限定符声明一个函数，它具有如下属性：</p><ul><li>标识Device侧函数强制内联，可以减少函数频繁调用产生的指令压栈、出栈的开销，但可能会导致算子二进制增加。</li><li>和C++函数修饰符inline的主要区别是Device侧__inline__是强制内联，C++的inline则是根据编译器优化选择性内联。</li><li>AI Core对函数嵌套深度有限制，一般推荐嵌套深度不超过4层。使用强制内联可以减少调用层次。</li></ul></li><li><p><strong>__cube__</strong></p><p>标识该核函数仅在Cube核执行。针对耦合模式的硬件架构，该修饰符不生效。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __cube__ void mmad_custom(GM_ADDR a, GM_ADDR b, GM_ADDR c)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    KernelMmad op;</span></span>
<span class="line"><span>    op.Init(a, b, c);</span></span>
<span class="line"><span>    op.Process();</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>__vector__</strong></p><p>标识该核函数仅在Vector核执行。针对耦合模式的硬件架构，该修饰符不生效。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __vector__ __global__ __aicore__ void add_custom(){}</span></span></code></pre></div></li><li><p><strong>__mix__(cube, vec)</strong></p><p>标识该核函数同时在Cube核和Vector核上执行。(cube, vec)分别表示核函数启动的Cube核和Vector核的配比，支持的配比为(1, 0)，(0, 1)，(1, 1)， (1, 2)。针对耦合模式的硬件架构，该修饰符不生效。</p></li><li><p><strong>__schedmode__(mode)</strong></p><p>标识该核函数的执行调度模式。如下图所示：</p><ul><li><p>mode = 0 : normal mode，尽可能选择空闲物理核下发执行核函数，若空闲物理核数无法满足当前核函数的需要，没有下发的部分等待核心空闲后执行。此时OP1和OP2算子会存在交叠执行（overlap）的情况。</p></li><li><p>mode = 1 : batch mode，在下发核函数时先进行判断，若空闲物理核数无法满足当前核函数的需要，则等待至空闲物理核数满足该核函数所需要的所有物理核时，同时下发执行，OP1和OP2的执行被切分（split）开，不会出现交叠执行的情况。</p></li></ul><p><img src="`+p+`" alt=""></p><p>在多流并发场景，多算子并行执行时，若执行总核数超过最大物理核数，且多个算子逻辑使用SyncALL等核间同步接口时，建议设置mode为1，防止多个算子之间互相等待空闲核调度，导致死锁。默认值mode为0。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __schedmode__(1) __global__ __mix__(1, 2) void OP1() // OP1使用了SyncAll接口，且存在多流并发的可能，需要设置batch mode（mode 1）</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::SyncAll();</span></span>
<span class="line"><span>    ....    </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span> __schedmode__(1) __global__ __mix__(1, 2) void OP2() // OP2使用了SyncAll接口，且存在多流并发的可能，需要设置batch mode（mode 1）</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::SyncAll();</span></span>
<span class="line"><span>    ....    </span></span>
<span class="line"><span>} </span></span>
<span class="line"><span>__schedmode__(0) __global__ __vector__ void OP3() {...} // OP3没有使用SyncAll接口，可以设置为normal mode(mode 0)，按照正常规则执行算子。</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>__global__ __vector__ void OP3() {...} // 不设置__schedmode__，默认为normal mode。</span></span></code></pre></div></li></ul><h2 id="函数标记宏" tabindex="-1">函数标记宏 <a class="header-anchor" href="#函数标记宏" aria-label="Permalink to &quot;函数标记宏&quot;">​</a></h2><ul><li><p>__simd_vf__</p><p>函数标记宏，用于标记SIMD VF入口函数，函数无返回值。使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/asc_vf_call-2.md" target="_blank" rel="noreferrer">asc_vf_call</a>调用SIMD VF入口函数，启动VF子任务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_vf__ inline void KernelAdd(__ubuf__ float* x, __ubuf__ float* y, __ubuf__ float* z)</span></span></code></pre></div><p>__simd_vf__标记的SIMD VF有以下入参约束：</p><ul><li><p>支持指针传参（Pass-by-Pointer），指针变量必须用__ubuf__地址空间限定符修饰。</p></li><li><p>不支持引用传参（Pass-by-Reference）。</p></li><li><p>不支持函数指针传参，函数对象。</p><p>__simd_vf__使用的示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_vf__ inline void simd_adds(__ubuf__ float *output, __ubuf__ float *input,</span></span>
<span class="line"><span>    uint32_t count, uint16_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;float&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;float&gt; dstReg;</span></span>
<span class="line"><span>    // asc_update_mask() will be supported later.</span></span>
<span class="line"><span>    // init MaskReg with the count of all numbers.</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg maskReg = AscendC::Reg::UpdateMask&lt;float&gt;(count);</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        // asc_load, asc_adds and asc_store will be supported later.</span></span>
<span class="line"><span>        // load data from UB to RegTensor.</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, input + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Adds(dstReg, srcReg, 1.0f, maskReg);</span></span>
<span class="line"><span>        // store data from RegTensor to UB.</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(output + i * one_repeat_size, dstReg, maskReg);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul></li><li><p>__simd_callee__</p><p>函数标记宏，函数可以有返回值，允许被SIMD VF入口函数或其他非入口函数调用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_callee__ inline float add(float x, float y)</span></span></code></pre></div></li></ul><h2 id="地址空间限定符" tabindex="-1">地址空间限定符 <a class="header-anchor" href="#地址空间限定符" aria-label="Permalink to &quot;地址空间限定符&quot;">​</a></h2><p>AI Core具备多级独立片上存储，各个地址空间独立编址，具备各自的访存指令，根据架构差异，有些存储空间具备统一地址空间（Generic Address Space），有些则没有。设备侧编程基于语法扩展允许地址空间作为合法的类型限定符，以提供针对不同地址空间的访问能力和地址空间合法性检查。</p><p><strong>表 2</strong> 地址空间映射关系</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;地址空间限定符&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;AI Core物理存储空间&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>gm</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;设备侧内存GM&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>ubuf</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Vector Unified Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>ca</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Cube L0A Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>cb</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Cube L0B Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>cc</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Cube L0C Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>cbuf</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Cube L1 Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>fbuf</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;Fixpipe Buffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;<strong>ssbuf</strong>&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50%&quot;&gt;&lt;p&gt;SSBuffer&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>地址空间限定符可以在变量声明中使用，用于指定对象分配的区域。如果对象的类型被地址空间名称限定，那么该对象将被分配在指定的地址空间中。同样地，对于指针，指向的类型可以通过地址空间进行限定，以指示所指向的对象所在的地址空间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// declares a pointer p in the __gm__ address space that</span></span>
<span class="line"><span>// points to an object(has int type) in the __gm__ address space</span></span>
<span class="line"><span>__gm__ int *p;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __aicore__ void foo(...)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  // declares an array of 4 floats in the private address space.</span></span>
<span class="line"><span>  float x[4];</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>地址空间限定符不能用于非指针返回类型，非指针函数参数，函数类型，同一个类型上不允许使用多个地址空间限定符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// OK.</span></span>
<span class="line"><span>__aicore__ int f() {...}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Error. Address space qualifier cannot be used with a non-pointer return type.</span></span>
<span class="line"><span>__ubuf__ int f() { ... }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// OK. Address space qualifier can be used with a pointer return type.</span></span>
<span class="line"><span>__ubuf__ int *f() { ... }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Error. Multiple address spaces specified for a type.</span></span>
<span class="line"><span>__ubuf__ __gm__ int i;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// OK. The first address space qualifies the object pointed to and the second</span></span>
<span class="line"><span>// qualifies the pointer.</span></span>
<span class="line"><span>__ubuf__ int * __gm__ ptr;</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p><strong>重要</strong>：不同地址空间指针的大小可能不同。例如，不能认为 sizeof(__gm__ int *)总是等于sizeof(__ubuf__ int *)，譬如编译器或许可能在某些系统上以32bit存储__ubuf__指针。</p></div><ul><li><p><strong>private地址空间</strong></p><p>private地址空间是大多数变量的默认地址空间，特别是局部变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// m is in a specific kernel parameter address space, </span></span>
<span class="line"><span>// it&#39;s physical location is implementation determined.</span></span>
<span class="line"><span>__global__ __aicore__ void foo(int m) {</span></span>
<span class="line"><span>  // OK. i is an int variable allocated in private address space</span></span>
<span class="line"><span>  int i;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__aicore__ void bar(int k) { //OK. k is in private address space</span></span>
<span class="line"><span>  // OK. i is an int variable allocated in private address space</span></span>
<span class="line"><span>  int i; </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>__gm__地址空间</strong></p><p>__gm__地址空间限定符用来表示分配于设备侧全局内存的对象，全局内存对象可以声明为标量、用户自定义结构体的指针。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__gm__ int *var; // var point to an array of int elements</span></span>
<span class="line"><span></span></span>
<span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    float a[3];</span></span>
<span class="line"><span>    int b[2];</span></span>
<span class="line"><span>} foo_t;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__gm__ foo_t *info; // info point to an array of foo_t elements</span></span></code></pre></div></li><li><p><strong>__ubuf__地址空间</strong></p><p>__ubuf__地址空间用来描述存储于AI Core核内UB存储空间的变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __aicore__ void foo() {</span></span>
<span class="line"><span>  // ptr is in private address space, point to __ubuf__</span></span>
<span class="line"><span>  __ubuf__ int *ptr;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p><strong>__ca__, __cb__, __cc__, __cbuf__地址空间</strong></p><p>上述几个地址空间主要用于特定的DMA指令访问，不具备标量直接访问能力。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class ObjTy{</span></span>
<span class="line"><span>  ObjTy(){...}</span></span>
<span class="line"><span>  void print(){...}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>  int a;</span></span>
<span class="line"><span>  int b;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __aicore__ </span></span>
<span class="line"><span>void foo(__ca__ int * ptr) { // Error. Cannot have __ca__</span></span>
<span class="line"><span>                             // qualifier in kernel arguments</span></span>
<span class="line"><span>  // OK</span></span>
<span class="line"><span>  __ca__ int *ptr; </span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul><h2 id="内置常量" tabindex="-1">内置常量 <a class="header-anchor" href="#内置常量" aria-label="Permalink to &quot;内置常量&quot;">​</a></h2><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.14838516148385%&quot;&gt;&lt;p&gt;常量名&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.847415258474154%&quot;&gt;&lt;p&gt;取值&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.00419958004199%&quot;&gt;&lt;p&gt;功能&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.14838516148385%&quot;&gt;&lt;p&gt;constexpr int32_t g_coreType&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.847415258474154%&quot;&gt;&lt;ul&gt;&lt;li&gt;AscendC::AIC&lt;/li&gt;&lt;li&gt;AscendC::AIV&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.00419958004199%&quot;&gt;&lt;p&gt;常量值由框架自动设置，AIC核下，配置为AscendC::AIC，AIV核下，配置为AscendC::AIV。&lt;/p&gt; &lt;p&gt;可以通过对该常量值的判断，来实现了AIV与AIC核代码的区分和隔离。功能等同于直接使用ASCEND_IS_AIV、ASCEND_IS_AIC。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="内置变量" tabindex="-1">内置变量 <a class="header-anchor" href="#内置变量" aria-label="Permalink to &quot;内置变量&quot;">​</a></h2><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.988401159884011%&quot;&gt;&lt;p&gt;变量名&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.977402259774017%&quot;&gt;&lt;p&gt;对应API&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.03419658034197%&quot;&gt;&lt;p&gt;功能&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.988401159884011%&quot;&gt;&lt;p&gt;block_num&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.977402259774017%&quot;&gt;&lt;p&gt;GetBlockNum&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.03419658034197%&quot;&gt;&lt;p&gt;当前任务配置的核数，用于代码内部的多核逻辑控制等。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.988401159884011%&quot;&gt;&lt;p&gt;block_idx&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.977402259774017%&quot;&gt;&lt;p&gt;GetBlockIdx&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.03419658034197%&quot;&gt;&lt;p&gt;当前核的索引，用于代码内部的多核逻辑控制及多核偏移量计算等。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>通常，建议用户使用内置变量对应的API获取所需值，不建议用户直接使用内置变量。因为内置变量反映的是单个硬件资源的配置信息，对于软件栈整合硬件资源、扩展硬件的功能，内置变量的值与实际语义可能不符。</p><p>例如，在Atlas 推理系列产品中，当启用KERNEL_TYPE_MIX_VECTOR_CORE时，算子会同时运行在AI Core和Vector Core上。此时，block_idx在这两种核心上都是从0开始计数，用户无法直接通过block_idx来切分数据和控制多核逻辑。而GetBlockIdx在Vector Core上对block_idx增加偏移量（AI Core的block_num），从而保证返回的值能够正确反映多核环境下的实际逻辑。</p><h2 id="simd与simt混合编程场景" tabindex="-1">SIMD与SIMT混合编程场景 <a class="header-anchor" href="#simd与simt混合编程场景" aria-label="Permalink to &quot;SIMD与SIMT混合编程场景&quot;">​</a></h2><p>SIMD与SIMT混合编程场景中，SIMT VF的入口函数使用__simt_vf__进行标识，通过在SIMD的__aicore__函数中使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/asc_vf_call.md" target="_blank" rel="noreferrer">asc_vf_call</a>调用SIMT入口函数。被SIMT VF入口函数调用的函数使用__simt_callee__进行标识。</p><ul><li><p>__simt_vf__</p><p>函数标记宏，用于标记SIMT VF入口函数，函数无返回值。使用asc_vf_call接口调用SIMT VF入口函数，启动VF子任务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_vf__ inline void KernelAdd(__gm__ float* x, __gm__ float* y, __gm__ float* z)</span></span></code></pre></div><p>__simt_vf__标记的SIMT VF函数支持的参数类型如下。__simt_vf__的使用示例请参考<a href="./../编程模型/AI-Core-SIMD编程/SIMD与SIMT混合编程.html#section776244992018">编程示例</a>。</p><ul><li>指针类型：__ubuf__ *、__gm__ *；</li><li>标量类型：bool、int8_t、uint8_t、int16_t、uint16_t、half、bfloat16、int32_t、uint32_t、float、int64_t、uint64_t。</li></ul></li><li><p>__simt_callee__</p><p>函数标记宏，用于标记SIMT VF非入口函数，函数可以有返回值，允许被SIMT VF入口函数或其他非入口函数调用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_callee__ inline float add(float x, float y)</span></span></code></pre></div></li></ul><p>Ascend C为SIMT编程、SIMD与SIMT混合编程提供了布尔、整形、浮点型的标量数据类型和短向量数据类型，提供了用于表达线程块、线程网格三维信息的内置变量。 关于内置数据格式的详细说明请参见<a href="./SIMT-BuiltIn关键字.html#section1835494915576">内置数据类型</a>，内置变量请参见<a href="./SIMT-BuiltIn关键字.html#section13165113520576">内置变量</a>。</p>`,29)])])}const b=s(e,[["render",o]]);export{d as __pageData,b as default};
